    if any(dep not in nodes for deps in nodes.values() for dep in deps):raise ValueError('unknown dependency')
    if isinstance(max_workers,bool) or not isinstance(max_workers,int) or not 1<=max_workers<=64:raise ValueError('invalid worker count')
